package com.example.api.service;

import java.util.List;

import com.example.api.entity.Pet;
import com.example.api.exception.ResourceNotFoundException;
import com.example.api.repository.PetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Business logic for the "Pet" API group.
 * Operations whose body only throws {@link UnsupportedOperationException} need your implementation.
 *
 * Generated by SpecForge from "Pet Store" (1.0.0). Safe to edit.
 */
@Service
@Transactional
public class PetService {

    private final PetRepository repository;

    public PetService(PetRepository repository) {
        this.repository = repository;
    }

    /**
     * <p>GET /v1/pets
     * <p>Implemented as a standard list operation.
     */
    public List<Pet> listPets() {
        return repository.findAll();
    }

    /**
     * <p>POST /v1/pets
     * <p>Implemented as a standard create operation.
     */
    public Pet addPet(Pet body) {
        // the id is generated by the database; ignore any id sent by the client
        body.setId(null);
        return repository.save(body);
    }

    /**
     * <p>GET /v1/pets/{petId}
     * <p>Implemented as a standard get operation.
     */
    public Pet getPet(Long petId) {
        return repository.findById(petId)
            .orElseThrow(() -> new ResourceNotFoundException("Pet not found: " + petId));
    }

    /**
     * <p>DELETE /v1/pets/{petId}
     * <p>Implemented as a standard delete operation.
     */
    public void deletePet(Long petId) {
        Pet existing = repository.findById(petId)
            .orElseThrow(() -> new ResourceNotFoundException("Pet not found: " + petId));
        repository.delete(existing);
    }
}
